//! Checks for the FFI ownership rules of spec `macos/0001` (AC-6).
//!
//! `docs/specs/macos/0001-sapaan-di-jendela-macos/index.md`, section
//! "Kepemilikan di batas FFI", says all boundary code is generated by
//! UniFFI: the hand written bridge in `crates/macos-ffi/` holds no `unsafe`,
//! and hand written Swift in `apps/macos/` uses no pointers. These tests
//! read those files as text, so plain `cargo test` catches drift without a
//! Swift toolchain. The bridge's own behaviour is tested by `forwards_to_core`
//! and the Swift suites; the fixed checks for AC-7 and AC-8 belong to scope
//! 002 and are not repeated here.

use std::fs;
use std::path::{Path, PathBuf};

const BRIDGE_LIB: &str = include_str!("../../macos-ffi/src/lib.rs");
const BRIDGE_MANIFEST: &str = include_str!("../../macos-ffi/Cargo.toml");

/// Build output folders under `apps/macos/` that are not source.
const BUILD_FOLDERS: [&str; 2] = [".build", "DerivedData"];

/// The repo root, two levels above this crate.
fn repo_root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../..")
        .canonicalize()
        .expect("the repo root exists")
}

/// Returns every file under `dir` whose name ends with `extension`,
/// skipping build output folders.
fn files_with_extension(dir: &Path, extension: &str) -> Vec<PathBuf> {
    let mut found = Vec::new();
    let mut pending = vec![dir.to_path_buf()];
    while let Some(folder) = pending.pop() {
        for entry in fs::read_dir(&folder).expect("source folder is readable") {
            let path = entry.expect("folder entry is readable").path();
            let name = path
                .file_name()
                .and_then(|n| n.to_str())
                .unwrap_or_default();
            if path.is_dir() && !path.is_symlink() {
                if !BUILD_FOLDERS.contains(&name) {
                    pending.push(path);
                }
            } else if name.ends_with(extension) {
                found.push(path);
            }
        }
    }
    found.sort();
    found
}

/// Covers AC-6: the bridge crate docs name the spec and state the copy rule.
#[test]
fn bridge_docs_point_to_the_spec_and_the_copy_rule() {
    let docs: String = BRIDGE_LIB
        .lines()
        .filter(|line| line.starts_with("//!"))
        .collect::<Vec<_>>()
        .join("\n");
    assert!(
        docs.contains("docs/specs/macos/0001-sapaan-di-jendela-macos/index.md"),
        "AC-6: bridge crate docs name the spec path"
    );
    assert!(
        docs.contains("every value that crosses is copied"),
        "AC-6: bridge crate docs state that every value is copied"
    );
}

/// Covers AC-6: `grep -rn unsafe crates/macos-ffi/src` prints nothing, for
/// every Rust file in the bridge, including ones added later.
#[test]
fn bridge_sources_hold_no_unsafe() {
    let sources = files_with_extension(&repo_root().join("crates/macos-ffi/src"), ".rs");
    assert!(
        sources.iter().any(|path| path.ends_with("src/lib.rs")),
        "AC-6: the bridge lib.rs is among the checked files: {sources:?}"
    );
    for path in sources {
        let text = fs::read_to_string(&path).expect("bridge source is readable");
        for (number, line) in text.lines().enumerate() {
            assert!(
                !line.contains("unsafe"),
                "AC-6: {}:{}: {line}",
                path.display(),
                number + 1
            );
        }
    }
}

/// Covers AC-6: the bridge manifest forbids `unsafe` code.
#[test]
fn bridge_manifest_forbids_unsafe_code() {
    let lints: Vec<&str> = BRIDGE_MANIFEST
        .lines()
        .map(str::trim)
        .skip_while(|line| *line != "[lints.rust]")
        .skip(1)
        .take_while(|line| !line.starts_with('['))
        .collect();
    assert!(
        lints.contains(&"unsafe_code = \"forbid\""),
        "AC-6: unsafe_code = \"forbid\" in the bridge [lints.rust]: {lints:?}"
    );
}

/// Covers AC-6: hand written Swift in `apps/macos/` uses no pointer types or
/// pointer helpers. Only the generated binding in `bindings/swift/` does.
#[test]
fn hand_written_swift_uses_no_pointers() {
    let sources = files_with_extension(&repo_root().join("apps/macos"), ".swift");
    assert!(
        sources
            .iter()
            .any(|path| path.ends_with("Interop/Greeter.swift")),
        "AC-6: the Interop greeter is among the checked files: {sources:?}"
    );
    for path in sources {
        let text = fs::read_to_string(&path).expect("Swift source is readable");
        for (number, line) in text.lines().enumerate() {
            let pointer_word =
                line.split(|c: char| !c.is_alphanumeric() && c != '_')
                    .find(|word| {
                        word.contains("Pointer")
                            || word.starts_with("withUnsafe")
                            || *word == "unsafeBitCast"
                    });
            assert!(
                pointer_word.is_none(),
                "AC-6: {}:{} uses {pointer_word:?}: {line}",
                path.display(),
                number + 1
            );
        }
    }
}
